import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/svs-label-macro.png",m=JSON.parse('{"title":"Aperio SVS Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Aperio SVS slides in your browser, from your disk or a link, with label and macro. Free, nothing to install or convert.","frontmatter":{"title":"Aperio SVS Slides in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Aperio SVS slides in your browser, from your disk or a link, with label and macro. Free, nothing to install or convert."},"headers":[],"relativePath":"guides/aperio-svs.md","filePath":"guides/aperio-svs.md"}'),s={name:"guides/aperio-svs.md"};function n(l,e,d,h,p,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="aperio-svs-slides-in-the-browser" tabindex="-1">Aperio SVS Slides in the Browser <a class="header-anchor" href="#aperio-svs-slides-in-the-browser" aria-label="Permalink to &quot;Aperio SVS Slides in the Browser&quot;">​</a></h1><p>Open the slides your Aperio scanner saves, as they are. Nothing to convert, nothing to upload. A large slide starts showing right away, because the viewer reads only the part you look at.</p><img width="3000" height="1900" src="'+i+'" alt="The Aperio slide CMU-1.svs open in the viewer: four pieces of H&amp;E stained tissue on the canvas, with the Label and Macro pictures under the file name in the right panel, and RGB contrast at 0 to 255" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of slides</strong>, in Chrome and Edge. One slide opens, several show a list. See <a href="./local-files.html#open-a-folder">Local Files</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>The slide.</strong> Zoom from the whole slide down to single cells.</li><li><strong>Label and Macro.</strong> The label photo and the overview photo appear under the slide&#39;s name. Click one to enlarge it. A label may show patient details. The viewer shows it and never saves or sends it.</li><li><strong>Compression.</strong> Slides saved as JPEG or JPEG 2000 open.</li><li><strong>Colour profile.</strong> A slide that carries its scanner&#39;s colour profile is drawn with it. ICC in the RGB settings turns it off. See <a href="./channels.html#icc-colour-profile">Channels</a>.</li><li><strong>Pixel size and magnification.</strong> Both come from the slide, so measurements read in µm and the zoom bar shows 20x or 40x. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Draw, measure and label shapes on the slide from the <strong>Annotations</strong> panel, or import a GeoJSON file. See <a href="./annotations.html">Annotations</a>.</p><h2 id="if-a-slide-does-not-open" tabindex="-1">If a Slide Does Not Open <a class="header-anchor" href="#if-a-slide-does-not-open" aria-label="Permalink to &quot;If a Slide Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>More than 4 GB</td><td>This SVS file is larger than 4 GB. The viewer cannot read it yet.</td></tr><tr><td>Another compression</td><td>This SVS file uses a compression the viewer cannot read yet (LZW).</td></tr><tr><td>Grey, 16-bit or more than three channels</td><td>This SVS file is not 8-bit RGB. The viewer cannot read it yet.</td></tr><tr><td>Not saved in tiles</td><td>This SVS file is not stored in tiles. The viewer cannot read it yet.</td></tr><tr><td>Not an Aperio file</td><td>This file is not an Aperio SVS file.</td></tr><tr><td>Damaged or cut short</td><td>This SVS file looks damaged or incomplete.</td></tr></tbody></table><p>Another slide format? Convert it to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><h2 id="measuring-pixel-values" tabindex="-1">Measuring Pixel Values <a class="header-anchor" href="#measuring-pixel-values" aria-label="Permalink to &quot;Measuring Pixel Values&quot;">​</a></h2><p>Safari draws JPEG slides with its own decoder, so pixel values differ slightly from Chrome and Firefox. For pixel measurements, use Chrome or Firefox.</p><h2 id="public-slides-to-try" tabindex="-1">Public Slides to Try <a class="header-anchor" href="#public-slides-to-try" aria-label="Permalink to &quot;Public Slides to Try&quot;">​</a></h2><p><a href="https://openslide.org" target="_blank" rel="noreferrer">OpenSlide</a> shares test slides in its <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Aperio/" target="_blank" rel="noreferrer">Aperio folder</a>, CC0. Download a slide, then drop it on the viewer.</p><p>More places to find public data: <a href="./remote-urls.html">Remote URLs</a>.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a slide by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the slide and open it from your computer.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots use <code>CMU-1.svs</code> from the OpenSlide test data, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The slide is read in your browser. Opening an SVS counts as one opened image of the kind &quot;Aperio SVS file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',26)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
